select t.table_name,
null as engine, ( select obj_description(c.oid, 'pg_class') from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace where n.nspname = t.table_schema and c.relname = t.table_name ) as table_comment, null::timestamp as create_time
t.engine, t.table_comment, t.create_time
from information_schema.tables t where t.table_schema =
current_schema() (select database())
and t.table_name = #{tableName}
